package agentusageview

import (
	"strconv"

	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// baseFooterHeight is the blank line and the message line (Rule 124).
const baseFooterHeight = 2

// View is the table, whatever it holds (Rule 139).
func (m Model) View() string {
	if m.level == levelAgents {
		return m.agentTable.View()
	}
	return m.table.View()
}

// GetTitle names the view.
func (m Model) GetTitle() string { return theme.IconAgentUsage + " Agent usage" }

// GetIcon returns nothing: the title carries the icon.
func (m Model) GetIcon() string { return "" }

// GetHeaderInfo counts the sessions on screen, and the ones not listed when
// there are some.
func (m Model) GetHeaderInfo(_ string) []shortcut.HeaderInfo {
	info := []shortcut.HeaderInfo{
		{Key: "Sessions", Value: strconv.Itoa(len(m.table.Visible())), Style: theme.HeaderValueStyle},
	}
	if m.omitted > 0 {
		info = append(info, shortcut.HeaderInfo{Key: "Skipped", Value: strconv.Itoa(m.omitted), Style: theme.HeaderValueStyle})
	}
	return info
}

// GetShortcuts returns the same keys in every state, none greyed: each one
// always acts here (Rule 130).
func (m Model) GetShortcuts() shortcut.Shortcuts {
	return shortcut.Shortcuts{
		{Key: "ctrl+r", Description: "Refresh"},
		{Key: "/", Description: "Filter"},
		{Key: "?", Description: "Help"},
	}
}

// GetFooterHeight budgets the footer (Rules 124, 136).
func (m Model) GetFooterHeight() int {
	return baseFooterHeight + m.activeFilterBar().ExtraHeight()
}

// RenderFooter renders the filter bar when visible, a blank line, and the
// message line.
func (m Model) RenderFooter(width int) string {
	line := theme.EmptyLineBg(width) + "\n" + m.footer.View(width, m.status())
	if bar := m.activeFilterBar(); bar.IsVisible() {
		return bar.View() + "\n" + line
	}
	return line
}

// status is derived on every frame, with no timer (Rule 128).
//
// The empty sentence needs the listing to be empty in total, not after the
// filter: a filter with no match is not a machine with no sessions.
func (m Model) status() sharedcomponents.Status {
	if m.level == levelAgents {
		return m.agentsStatus()
	}
	switch {
	case m.loadErr:
		return sharedcomponents.Status{
			Text:  "Failed to list Claude Code sessions — check logs",
			Level: sharedcomponents.LevelError,
		}
	case m.loading:
		return sharedcomponents.Status{Text: "Reading Claude Code sessions...", Spinner: true}
	case len(m.table.Items()) == 0:
		return sharedcomponents.Status{Text: "No Claude Code sessions found in " + theme.FoldHome(m.root)}
	}
	return sharedcomponents.Status{}
}

// agentsStatus is the footer state of the agents level.
func (m Model) agentsStatus() sharedcomponents.Status {
	switch {
	case m.agentsErr:
		return sharedcomponents.Status{
			Text:  "Failed to read this session — check logs",
			Level: sharedcomponents.LevelError,
		}
	case m.agentsLoading:
		return sharedcomponents.Status{Text: "Reading session...", Spinner: true}
	}
	return sharedcomponents.Status{}
}
package agentusageview

import "github.com/anthnel/devdesk/internal/ui/help"

// GetHelpContent returns the help for `?` (Rule 114).
func (m Model) GetHelpContent() help.Content {
	return help.Content{
		Title: "Agent usage",
		Description: "The Claude Code sessions found on this machine, newest first. " +
			"Only where and when a session ran is read — nothing a session says.",
		KeyBindings: []help.KeyBinding{
			{Key: "ctrl+r", Description: "Read the sessions again"},
			{Key: "/", Description: "Filter by project or session ID"},
			{Key: ".", Description: "Cycle the sort column"},
			{Key: "ctrl+p", Description: "Open command mode"},
			{Key: "?", Description: "Show this help"},
		},
		Sections: []help.Section{
			{
				Title: "Columns",
				Body: "Project: the working directory the session ran in, with your home folded to ~. " +
					"A long path is cut from the left so the project's own name stays visible; a dash means the transcript named none.\n" +
					"Last active: when the session's transcript was last written, in local time.\n" +
					"Session: the start of the session ID. The filter matches the full ID.",
			},
			{
				Title: "Where sessions come from",
				Body: "Claude Code keeps one transcript per session under projects/ in its configuration directory: " +
					"$CLAUDE_CONFIG_DIR when set, otherwise ~/.claude. " +
					"Claude Code deletes old transcripts itself (after 30 days by default), so older sessions disappear from here too.\n" +
					"Sessions that could not be listed (symbolic links, which are refused rather than followed, unreadable directories, " +
					"or sessions beyond the listing cap) are counted as Skipped in the header.",
			},
			{
				Title: "Privacy",
				Body: "Only the working directory and the file date are shown. " +
					"Prompts, replies and tool output are never read into this view, never displayed and never logged.",
			},
		},
	}
}
// Package agentusageview is the `:agent-usage` screen: the Claude Code
// sessions found on this machine.
//
// It reads transcripts' working directory and date only, never their content
// (internal/agentusage owns that guarantee).
package agentusageview

import (
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/config"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// sessionRow is one table row. project is computed once, in Update, so a Cell
// never touches the file system or the environment.
type sessionRow struct {
	agentusage.Session
	project string // theme.FoldHome(Project), or "-" when unknown
}

// sessionListLoadedMsg carries one listing. gen drops an answer to a read that
// a newer one has superseded.
type sessionListLoadedMsg struct {
	gen     int
	root    string
	listing agentusage.Listing
	err     error
}

// sessionUsageLoadedMsg carries one parsed session. gen is agentGen at the time
// the parse started: it drops the answer for a session left or re-read since.
type sessionUsageLoadedMsg struct {
	gen   int
	usage agentusage.Usage
	err   error
}

// level is the screen on view: the sessions, or the agents of one session.
type level int

const (
	levelSessions level = iota
	levelAgents
)

// Model is the agent usage view.
type Model struct {
	table   datatable.Model[sessionRow]
	spinner spinner.Model
	footer  sharedcomponents.FooterMessage

	// level says which table is on screen. The sessions table keeps its cursor
	// and filter while the agents level is open.
	level level
	// agentTable lists the agents of open.
	agentTable datatable.Model[agentRow]
	open       agentusage.Session
	// agentGen numbers the parses, as gen numbers the listings.
	agentGen      int
	agentsLoading bool
	// agentsErr says the most recent parse failed (a state, like loadErr).
	agentsErr bool
	// width and height are the last viewport size, for both tables.
	width, height int

	// gen numbers the reads; only the answer to the latest one is kept.
	gen     int
	loading bool
	// loadErr says the most recent read failed. It is a state rather than a
	// timed message so the empty-listing sentence cannot take its place.
	loadErr bool
	// root is the projects directory the last successful read listed.
	root    string
	omitted int
}

// New builds the view with its first read pending.
func New(_ *config.Config) Model {
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	return Model{
		loading: true,
		spinner: sp,
		table: datatable.New(datatable.Config[sessionRow]{
			Columns: sessionColumns(),
			// The listing arrives newest first, which is the order wanted.
			SortColumn: -1,
		}),
		agentTable: datatable.New(datatable.Config[agentRow]{
			Columns: agentColumns(),
			// The order is the tree: orchestrator, then sub-agents.
			SortColumn: -1,
		}),
	}
}

// Init starts the first read and the spinner.
func (m Model) Init() tea.Cmd {
	cmds := []tea.Cmd{listSessionsCmd(m.gen), m.spinner.Tick}
	if m.level == levelAgents {
		cmds = append(cmds, parseSessionCmd(m.agentGen, m.open.Parent))
	}
	return tea.Batch(cmds...)
}
package agentusageview

import (
	"fmt"
	"sort"
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

const (
	// noModel stands for an agent whose transcript named no model.
	noModel = "-"
	// unknownType stands for a sub-agent whose meta file gave no type.
	unknownType = "unknown"
	// orchestratorLabel is the Agent cell of the main agent.
	orchestratorLabel = "orchestrator"
	// partialMark prefixes an output count that is a floor, not an exact value.
	partialMark = "≥ "
	// stem and lastStem draw the tree branch in front of a sub-agent's type.
	stem     = "├─ "
	lastStem = "└─ "
)

// agentRow is one line of the agents table: an agent, and whether it is the
// last sub-agent, which decides the shape of its branch.
type agentRow struct {
	agentusage.Agent
	last bool
}

// agentRows orders a session's agents: the orchestrator first, then the
// sub-agents by ID. The sort is stable so equal IDs keep their input order.
func agentRows(u agentusage.Usage) []agentRow {
	var main, subs []agentusage.Agent
	for _, a := range u.Agents {
		if a.Main {
			main = append(main, a)
		} else {
			subs = append(subs, a)
		}
	}
	sort.SliceStable(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })

	rows := make([]agentRow, 0, len(u.Agents))
	for _, a := range main {
		rows = append(rows, agentRow{Agent: a})
	}
	for i, a := range subs {
		rows = append(rows, agentRow{Agent: a, last: i == len(subs)-1})
	}
	return rows
}

// agentColumns describes the agents table. Nothing sorts: the order is the
// tree. Cache columns give way first on a narrow terminal, writes before reads.
func agentColumns() []datatable.Column[agentRow] {
	count := func(title string, width int, tokens func(agentRow) int64) datatable.Column[agentRow] {
		return datatable.Column[agentRow]{
			Title: title, Sizing: datatable.SizingFixed, MinWidth: width,
			Cell:  func(r agentRow) string { return formatTokens(tokens(r)) },
			Style: func(r agentRow) lipgloss.Style { return dimWhen(tokens(r) == 0) },
		}
	}
	in := count("In", 6, func(r agentRow) int64 { return r.Tokens.Input })
	cacheRead := count("Cache read", len("Cache read"), func(r agentRow) int64 { return r.Tokens.CacheRead })
	cacheRead.Optional = true
	cacheWrite := count("Cache write", len("Cache write"), func(r agentRow) int64 { return r.Tokens.CacheWrite })
	cacheWrite.Optional, cacheWrite.DropFirst = true, true
	total := count("Total", 6, func(r agentRow) int64 { return r.Tokens.Total() })

	out := count("Out", 7, nil)
	out.Cell = outCell
	out.Style = func(r agentRow) lipgloss.Style { return dimWhen(r.Tokens.Output == 0) }

	return []datatable.Column[agentRow]{
		{Title: "Agent", Sizing: datatable.SizingContent, MinWidth: 14, Cell: roleCell, Search: agentSearch,
			Style: func(r agentRow) lipgloss.Style { return dimWhen(!r.Main && r.Type == "") }},
		{Title: "Model", Sizing: datatable.SizingContent, MinWidth: 12, Flex: 2, Cell: modelsCell, Search: modelsCell,
			Style: func(r agentRow) lipgloss.Style { return dimWhen(len(r.Models) == 0) }},
		in, out, cacheRead, cacheWrite, total,
	}
}

// dimWhen is Rule 122's colour discipline: a zero or a placeholder is dim,
// anything else keeps the default colour.
func dimWhen(dim bool) lipgloss.Style {
	if dim {
		return theme.DimStyle
	}
	return lipgloss.NewStyle()
}

// agentSearch is what `/` matches in the Agent column: the role and the ID,
// which no column shows.
func agentSearch(r agentRow) string { return roleCell(r) + " " + r.ID }

// roleCell is the Agent cell: "orchestrator", or the sub-agent's type behind
// its branch.
func roleCell(r agentRow) string {
	if r.Main {
		return orchestratorLabel
	}
	typ := r.Type
	if typ == "" {
		typ = unknownType
	}
	if r.last {
		return lastStem + typ
	}
	return stem + typ
}

// modelsCell lists the models the agent used.
func modelsCell(r agentRow) string {
	if len(r.Models) == 0 {
		return noModel
	}
	return strings.Join(r.Models, ", ")
}

// outCell is the output count. A sub-agent still being written is a floor and
// says so; the orchestrator never does, its transcript is the one being read.
func outCell(r agentRow) string {
	out := formatTokens(r.Tokens.Output)
	if !r.Main && r.PartialOutput() {
		return partialMark + out
	}
	return out
}

// formatTokens renders a count compactly, floored to one decimal: 1099 is
// "1.0k", never "1.1k". From 100 of a unit up the decimal is dropped.
func formatTokens(n int64) string {
	units := []struct {
		size   int64
		suffix string
	}{
		{1_000_000_000_000, "T"}, {1_000_000_000, "B"}, {1_000_000, "M"}, {1_000, "k"},
	}
	for _, u := range units {
		if n < u.size {
			continue
		}
		tenths := n / (u.size / 10) // divide first: n*10 would overflow
		if tenths >= 1000 {
			return fmt.Sprintf("%d%s", tenths/10, u.suffix)
		}
		return fmt.Sprintf("%d.%d%s", tenths/10, tenths%10, u.suffix)
	}
	return fmt.Sprintf("%d", n)
}

