	keys := map[string]bool{}
	for _, b := range c.KeyBindings {
		keys[b.Key] = true
	}
	for _, k := range []string{"ctrl+r", "/", "?"} {
		if !keys[k] {
			t.Errorf("help lacks key %q", k)
		}
	}
	if len(c.Sections) < 3 {
		t.Fatalf("help needs at least 3 sections (columns, sources, privacy), got %d", len(c.Sections))
