func TestShortcutsAreGreyedByLevelAndByRow(t *testing.T) {
	tests := []struct {
		name         string
		m            Model
		openEnabled  bool
		closeEnabled bool
	}{
		{"sessions with a row", withSessions(t, "/p/a.jsonl"), true, false},
